        "passageTitle": "張岱《陶庵夢憶‧自序》",
        "passage": "雞鳴枕上,夜氣方回,因想余生平,繁華靡麗,過眼皆空,五十年來,總成一夢。……遙思往事,憶即書之,持向佛前,一一懺悔,不次歲月,異年譜也;不分門類,別志林也。偶拈一則,如遊舊徑,如見故人、城郭、人民,翻用自喜,真所謂癡人前不得說夢矣。昔有西陵腳夫,為人擔酒,失足破其甕,念無以償,癡坐佇想曰:「得是夢便好。」一寒士鄉試中式,方赴鹿鳴宴,恍然猶意非真,自嚙其臂曰:「莫是夢否?」一夢耳,惟恐其非夢,又惟恐其是夢,其為癡人則一也。余今大夢將寤,猶事雕蟲,又一番夢囈。(張岱《陶庵夢憶‧自序》)",
        "question": "關於上文「腳夫」、「寒士」的敘述,最適當的是:",
