        "passage": "【甲】人為萬物之靈,志有萬端之異。學書學詩均從所好,工書工畫各有專長,是故咳唾珠玉,謫仙闥詩學之源;節奏鏗鏘,蔡女撰胡笳之拍,此皆不墜聰明,而有志竟成者也。若夫銀鉤鐵畫,固屬難窺;儷白妃青,亦非易事。余於停機教子之暇,調藥助夫之暇,竊慕管夫人之墨竹,紙上生風;敢籍陶淵明之黃花,圖中寫影。庶幾秋姿不老,四座流芬,得比勁節長查,千人共仰,竟率意而鴉塗,莫知其鳩拙云爾!(張李德和〈畫菊自序〉)\n【乙】茲就詞章論,世多訾女子之作,大抵裁紅刻翠,寫怨言情,千篇一律,不脫閨人口吻者,予以為抒性情,本應如其分,惟須推陳出新,不襲窠臼,尤貴格律雋雅,情性真切,即為佳作。詩中之溫、李,詞中之周、柳,皆以柔麗擅長,男子且然,況於女子寫其本色,亦復何妨?(呂碧城〈女界近況雜談〉)\n【呂碧城(1883～1943),被譽為近三百年來最後一位女詞人。】",
