        "passage": "周厲王使芮伯帥師伐戎,得良馬焉,將以獻於王。芮季曰:「不如捐之。王欲無厭,而多信人之言。今以師歸而獻馬,王之左右必以子獲為不止一馬,而皆求於子。子無以應之,則將醫於王,王必信之。榮夷公果有求馬,弗得,遂譖諸王曰:「伯也隱。」王怒逐芮伯。君子謂芮伯亦有罪焉。爾知王之瀆貨而啟之,芮伯之罪也。(劉基《郁離子‧獻馬》)",
