        "question": "資料丙《古蹟指定及廢止審查辦法》為民國108年修訂版,若以資料丙審視資料甲,關於①、②兩項推論的研判,最適當的是:\n①鄭用錫墓展現清代「營造技術流派特色」,而列為國定古蹟。\n②王得祿墓的歷史價值,可能是被列入古蹟的條件之一。",
