        "passageId": "chinese-real-111-p23",
        "passageTitle": "《論語》《孟子》原文與朱熹解說",
        "passage": "【甲‧《論語》原文與朱熹的解說】\n子曰:「君子有三畏:畏天命,畏大人,畏聖人之言。小人不知天命而不畏也,狎大人,侮聖人之言。」\n朱熹的解說:①「大人」不止有位者,是指有位、有齒、有德者。②「畏天命」三字好。是理會得道理,便謹去做,不敢違,便是畏之也。如非禮勿視聽言動,與夫戒慎恐懼,皆所以畏天命也。③要緊全在知上。纔知得(天命),便自不容不畏。\n【乙‧《孟子》原文與朱熹的解說】\n說大人,則藐之,勿視其巍巍然。堂高數仞,榱題數尺,我得志,弗為也;食前方丈,侍妾數百人,我得志,弗為也;……在彼者,皆我所不為也,在我者,皆古之制也。吾何畏彼哉?\n朱熹的解說:①這為世上有人把大人許多崇高富貴當事,有言不敢出口,故孟子云爾。②《論語》說「畏大人」,此卻說「藐大人」,大人固當畏,而所謂「藐」者,乃不是藐他,只是藐他許多「堂高數仞,榱題數尺」之類。\n【榱題:屋椽的兩端之處。】",
        "question": "下列敘述,不符合資料甲意旨的是:",
