        "question": "關於下文「做菜」與「作文」之間的譬喻,說明最適當的是:\n滿洲菜多燒煮,漢人菜多羹湯,童而習之,故擅長也。漢請滿人,滿請漢人,各用所長之菜,轉覺入口新鮮,不失邯鄲故步。今人忘其本分,而要格外討好。漢請滿人用滿菜,滿請漢人用漢菜,反致依樣葫蘆,有名無實,畫虎不成反類犬矣。秀才下場,專作自己文字,務極其工,自有遇合。若逢一宗師而摹仿之,逢一主考而摹仿之,則掉皮無真,終身不中矣。(袁枚《隨園食單》)\n【下場:進入考場。】",
