        "passage": "枯山枯水庭園以砂石為主,但是幾乎每一方石庭都缺少不了綠色的點綴。談及日本庭園之綠意,除了草木之外,青苔也是構成的一大要素,【甲】,尤其是京都的庭園,如果沒有青苔,勢將減色不少。苔本是繁殖於地面的一種蘚類植物,只要氣候低濕,可以不種自衍。但是日本的庭園崇尚蒼老之美,【乙】,因此它也就變成了代表庭園歷史的一種標誌了。由於苔本身具有一種厚重的質感,其色雖濃翠,卻不綺豔,【丙】,加以苔本身所給予人時間之聯想,【丁】,所以在文學上,任何一個名詞,只要冠以「苔」字,立刻能造成蒼涼悲寂的效果,如「苔階」、「苔徑」、「苔井」、「苔池」。而當你面對京都的苔庭時,這蒼涼悲寂的情調就更具體的呈現在眼前了。(改寫自林文月〈京都的庭園〉)",
