        "passageTitle": "洪繻〈籌海議〉",
        "passage": "我果戰士有勇,大將有謀,成算在胸,地利足恃,猶不如誘之登岸而設伏殲之。不然,汪洋海上以數百人操一舟,東馳西突,以角逐勝負不可知之地,我即無恙,而彼之所挾者小,我之所勞者大,設防不豫,形勢不亦懸乎!誘之上岸,非有成算,則斷不可。蓋敵一登陸,民心易動,軍心易震,非宿有強兵不能得手也。生,臺人也,為臺灣計,臺北可誘之近岸,臺南則不可。蓋臺北港道深通而有屏蔽,彼之駐輪甚便;若登岸,則反失近侍。臺南則港門雖深,風浪甚苦,四圍無山,港中非可駐輪;彼不登岸,不能久居也。若臺中諸港,沙線淺瀨,難駛鐵船。然澎湖不守,則敵人得之,安穩收泊。有時長輪四掠,有時載小艇窺閱,臺中難防,臺南、北亦可慮。(洪繻〈籌海議〉)",
