        "passageTitle": "陸游〈跋李莊簡公家書〉",
        "passage": "李丈參政罷政歸鄉里時,某年二十矣。時時來訪先君,劇談終日。每言秦氏,必曰「咸陽」,憤切慨然,形於色辭。一日平旦來共飯,謂先君曰:「聞趙相衢州,悲憂出涕。僕不然,誚令下,青鞋布襪行矣,豈能作兒女態耶!」方言此時,目如炬,聲如鐘,其英偉剛毅之氣,使人興起。後四十年,偶讀公家書,雖徒海表,氣不少衰,叮嚀訓誡之語,皆足垂範百世,誦想其青鞋布襪時。淳熙戊申五月己未,笠澤陸某題。(陸游〈跋李莊簡公家書〉)",
        "question": "關於文中李參政的敘述,最適當的是:",
