        "question": "關於「祕密」的看法,符合下文敘述的是:\n當祕密出現在親近的人際關係中,每個人都覺得刺目——我隱匿了最後也可能是最重要的一條線索,阻止你順暢讀取我全部的檔案。那對愛是多大的殺傷力!這個世界於是鼓勵坦白,彷彿只要開誠布公,必能互相理解、擁抱,痛哭流涕和解。但祕密卻固執地打破了理性架構的神話,讓人類理解語言的侷限,發現自己畢竟掙脫不了那些幽暗的本能,及孤獨如何成為每個人真正的生命基調。\n害怕孤獨的人為了裝作一無所瞞,以爭取想像中的友誼,於是開始訴說祕密。祕密換祕密,那是別人的定情儀式,但我們不說自己的祕密。訴說別人祕密是一種無本生意,也是一種聲東擊西的謊計。當所有人都忙著訴說其他人的祕密,自己的祕密就擺脫了被刺探的危險。想要摻人耳目,是另一個人祕密開始出土的原因。(改寫自胡晴舫〈祕密〉)",
