        "question": "下列兩節現代詩,均以賴和為寫作題材。關於詩意的解讀,適當的是:\n甲、販夫的賣菜籃／從泛黃的紙張中傳來／殖民的申誡／帝國的律令／不過是根被折斷的秤錘呀／在不等重的兩端／丈量用聽診器／也無法診療的喘鳴／沉吟為一位詩人(洪崇傑〈稱仔的彼端——致賴和〉)\n乙、你與所有人／都曾捂著嘴、駝著背走過／日本軍警到處買站的街頭／在你自己的彰化媽祖宮用聽診器／像順風耳般,聽篩所有病人心房裡／癱瘓的故事與詩歌／住滿泰得參、林先生、添福、阿全、其那魯道……／你堅決帶他們走出情節與格律／到軍刀與竽棍林立的廣場大聽遊行／在文藝欄一遍遍排版複刻中／把他們供奉在文壇(解昆樺〈在囚獄中獲致潔淨的光〉)",
