        "passage": "【甲】菊花開,正歸來。伴虎溪僧鶴林友龍山客,似杜工部陶淵明李太白,有洞庭柑東陽酒西湖蟹。哎!楚三閭休怪。(〔元〕馬致遠〈撥不斷〉)\n【乙】長醉後方何礙?不醒時有甚思?糟醃兩個功名字,酩淨千古興亡事,麴埋萬丈虹霓志。不達時皆笑屈原非,但知音耳笑陶潛是。(〔元〕白樸〈寄生草〉)\n【酩:沒過濾的酒。淨:同「淹」,淹沒。】",
