        "passageTitle": "改寫自徐平〈一個屈原,各自表述——政大廖棟樑揭開屈原的百變面紗〉",
        "passage": "屈原已經成為一個符號和象徵。\n漢代,屈原的爭議主要落於「怨慍」。儒家對情感表達的理想是「樂而不淫,哀而不傷」。肯定屈原的人以注解家經書的方式注《楚辭》,試圖建立其經典地位,認為屈原和《詩經》一樣「怨誹而不亂」,可與日月爭光。批評屈原的人認為屈原在〈離騷〉有著歌泳式的表達,甚至悲壯地付出生命,與儒家中庸之道產生劇烈拉鋸。\n宋朝遭外族侵門踏戶,激發民族情感。《楚辭》讀者對屈原情感表現的理解,不同於漢代只從忠君脈絡詮釋,轉而強調其愛國之心,以國家民族興亡的高度,將「當怨與否」的倫理內涵重新審視,由此確立屈原情感的正當性。\n明代黃文煥因蒙冤下獄,對屈原不被理解的痛苦感同身受。在獄中著《楚辭聽直》,為屈原的忠義之心辯護,希望有人也能替他昭雪冤屈。\n屈原之於現代讀者的意義,與社會文化語境相關,面對抗戰,屈原愛國的面向被重新加強。隨著端午節被確立為詩人節,學者開始思考「詩人何為」,從中探討文學與政治的關係。當個人理想遭遇挫折,就像屈原不被楚王了解,這時該不該執著?可藉由屈原「舉世皆濁我獨清」的心緒,思考理想和世界的衝突。(改寫自徐平〈一個屈原,各自表述——政大廖棟樑揭開屈原的百變面紗〉)",
        "question": "依據甲、乙二曲和丙文,關於歷代對屈原的看法,敘述適當的是:",
