        "question": "關於古典的閱讀策略,最符合甲、乙二文敘述的是:(占2分,單選題)\n(A)甲文指出廣泛接受並適當批判古典,可讓思想開闊深厚\n(B)乙文強調閱讀古典應從庶民角度出發,以了解時代脈動\n(C)甲文認為應獨自體會深思,乙文認為不妨倚賴專家引導\n(D)二文皆主張藉由同情共感的體證,可消解字面理解障礙",
