        "passage": "【甲】古典是穿越世代的共有智慧,也是橫跨國界的共享遺產。\n在人文教育上,思想的開放是終極目標。文化應通過批判性地消化繼承,而不能全盤否定或租暴對抗。美國獨立成功,文化上仍與英國文學緊密接連。主張脫亞入歐的日本,從來就持續接納儒學的薰陶。\n古典之成為古典,並不是因為年齡蒼老,而是因為它經過不同歷史階段的過濾與篩選,禁得起解釋、開發、創造。無論時代如何進步,只有人性是千古不變。即使是千年以前的《詩經》,在恰當時刻也能感發不同時代的心靈。\n追求進步並非要摒棄古典,而應以開放的精神重新檢視。所有的古典,經過閱讀、解釋、再創造,就會變成當代價值的一部分。\n經過閱讀與再閱讀,創造與再創造,古典就是永遠的現代。(改寫自陳芳明〈古典是永遠的現代〉)\n【乙】古典不等於古文,年代也未必久遠。披頭四的歌曲迄今不過半世紀,但對後世音樂影響深遠;蘇聯導演艾森斯坦《波坦金戰艦》的蒙太奇手法,如今已是電影的基本文法。這些在當時展現新手法或開創新視野的作品,後人愈是追隨,愈能顯出其恆久的地位。\n2006年,龜山郁夫新譯杜思妥也夫斯基1880年的《卡拉馬助夫兄弟們》,一出版即暢銷百萬冊。優秀的譯筆能賦予古典現代生命。\n古典的耀眼光彩從不會因古老而褪色。《論語》提供的建言,到今日仍可為人生的困境解惑。古典有時理解不易,可參考專家的引導,但不要變成先入之見。正阿子規認為《古今和歌集》不及《萬葉集》,但他是為了替低迷的短歌灌注活力,才批判有貴族傾向的和歌,讀者不能斷章取義。(改寫自齋藤孝著,莊雅琇譯《古典力》)",
        "question": "甲、乙二文均認為古典具有永恆性。明代許潮《赤壁遊》雜劇,對蘇軾〈赤壁賦〉既有承繼又有創新,請依下列引文回答問題:\n〔生〕今山水星月,相照若昔,而英雄何寥寥也!吾四人遊賞於此,幸各能詩。可將曹孟德、孫仲謀、劉玄德、周公瑾,寫作四圖,各拈取一圖,吟詩一首,以見弔古斷案。【眾】最好!……〔生〕我等吟詠已完,可斟酒來。各照題目,嘆他一番。……(寄豢兒)〔生〕躍馬意何長,視東吳已入囊,舳艫千里旌旗颺。橫槊時氣揚,釃酒時態狂,誰知一火把神魂喪。〔合〕嘆興亡,江山如故,何處覓曹郎?……(祝英台)〔生〕把古今愁,廓廟悶,聊付與滄浪。\n【生:劇中扮演蘇軾。眾:指蘇軾外的黃庭堅、佛印、漁父。寄豢兒、祝英台:皆曲牌名。】\n(1)舟中四人抽籤後,賦詩的規則為何?(占2分,作答字數:20字以內,不可抄錄原文。)\n(2)劇曲中,唱詞常表述人物的心聲。請問:①眾人〔合〕唱,除表達物是人非的喟嘆,更反映出世人對個體生命有什麼「共同的焦慮」?②許潮藉東坡之口道出:「聊付與滄浪」,對此一焦慮所持的態度是什麼?(①占2分,作答字數:10字以內;②占2分,作答字數:10字以內)",
        "explanation": "【滿分參考答案】\n(1)各就所抽中的人物,賦詩一首歌詠。或:吟詠所抽中的人物。\n或:各就所抽中的人物,賦詩一首來懷古。\n(2)①生命有限。或:死亡不可抗拒。或:人終有一死。\n②隨任自然。或:曠達。或:釋懷。\n\n【評分原則】\n第35題(1):能寫出參考答案之大意 2分;未作答或答案完全錯誤 0分。\n第35題(2):能寫出參考答案大意,且敘述完整 4分;答案敘述部分錯誤或不完整 2分;未作答或答案完全錯誤 0分。\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
