        "question": "上文認為,《獅子王》的創造來自《哈姆雷特》的再閱讀。請參考「創意技能金字塔」(由下而上:產生點子/識別好點子/發展點子/闡述點子/爭取支持/堅持到最後),就文中觀點回答下列問題:\n(1)《獅子王》的編劇將構想連結《哈姆雷特》後,自認能達金字塔「識別好點子」階段的主要理由是什麼?(占2分,作答字數:20字以內。)\n(2)當《獅子王》構想進到金字塔的「爭取支持」階段,《哈姆雷特》能對高層主管產生說服作用,是基於哪二個理由?(占4分,作答字數:40字以內。)",
        "explanation": "【滿分參考答案】\n(1)反映人性現實。或:哈姆雷特反映的人性現實能獲得普遍回響。\n(2)高層主管對新故事有熟悉感,提供行銷的參考座標。\n或:能和經典故事連結,找到向觀眾行銷的著力點。\n\n【評分原則】\n第37題(1):能正確寫出參考答案之文句 2分;未作答或答案完全錯誤 0分。\n第37題(2):能寫出參考答案大意,且敘述完整 4分;答案敘述部分錯誤或不完整 2分;未作答或答案完全錯誤 0分。\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
