        "id": "chinese-real-113-q6",
        "origNo": 6,
        "sourceYear": 113,
        "passageId": "chinese-real-113-p6",
        "passageTitle": "改寫自鄭至慧、劉斐玟等相關研究論文",
        "passage": "中國湖南省江永地區,一種神祕的菱形文字——女書——悄悄流傳超過百年。它是一種使用當地方言,須以「唱誦」方式表達與理解的表音文字。女人用它來自傳訴情、互通心跡、結交姊妹、祝禱祈願、傳說紀聞……。\n江永是典型的農業社會,女孩從小「不得亂步出娘房」,因此未嫁的女兒稱作「樓中女」。未嫁的女兒在娘樓做女紅時,邊唱歌、寫女書、織女書字,進入正統教育體系之外的知識系統,且因熱愛女書而結為姊妹。當有姊妹出嫁,每個姑娘從婚前幾天便開始哭嫁,饋贈女書留念,感慨女性身不由己的共同命運,娘樓是她們建立封閉又親密的女性空間,但事實上又是「無常」的象徵。\n在以哭嫁為主題的女書作品中,常常描述父系社會婚姻將女人從原生土壤連根剖起的滋味,顯示哭嫁不僅是少女面對未知命運的恐懼,更是女人剪斷血緣、地緣與人緣臍帶時的哀號。但也由於有女書,因而女性即使文盲婦女喪失向外通訊、結盟的能力。姊妹們的通信中苦多樂少,但總是盡心相勸、彼此扶持。\n她們透過女書,在社會現實與磨難中掙扎、拉鋸、妥協,尋找生存之道。甚至在書寫過程中,執筆者也不止於代表,悲憐勤解的同時,常將自己的身世寫了進去,形成風格特殊的「參與寫作」。\n關於女書的起源至今仍是個謎,江永女性發明了世界上獨一無二的女書,但因以土話為音,加上地方阻隔,僅局限於江永一帶流傳。也由於女性死後女書多作為殉葬而被焚毀,以及隨著教育的普及、傳統習俗、社會情境的改變等因素,女書逐漸式微。然而,女書的研究與應用方興未艾,尤其是在消費時代裡,女書反成為一種時尚符號,常出現在文創設計中。(改寫自鄭至慧、劉斐玟等相關研究論文)",
