        "question": "下列女書作品,不是表現「女性婚後的失落」的是:\n(A)將說嫁妝兩半分,又氣淚流離一字。吃盡千般鹽香味,做盡媳婦一字難\n(B)粗字粗針到貴府,只望姑娘請諒寬。不比貴家禮義全,你在高堂好過日\n(C)十八歲女三歲郎,夜間洗腳抱上床。睡到五更奶吃,我是寒妻不是娘\n(D)他娘心中用計策,暗中叫子到別州。瞞起佗身不知得,不知丈夫到哪方",
