        "question": "迷因(meme)是文化傳遞的微型單位,經由模仿、複製、改作,承載片段資訊或觀點,透過語文、圖片或影音等型態流傳,帶來影響。「周處除三害」即屬迷因,依據右列電影《周處除三害》簡介,關於其模仿、改作傳說,說明最適當的是:\n【題目補充材料:電影《周處除三害》簡介——亡命天涯的槍擊犯陳桂林,誤信醫師的診斷,以為自己身罹絕症。在醫師勸說自首後,因不希望自己死後被別人遺忘,決心以惡制惡,追殺排名在他之前的二大通緝要犯。最後投案自首,接受槍決伏法。陳桂林自以為是現代周處,卻沒想到困住他,讓他逃無可逃的,從來都不是外在環境,而是內心的貪、嗔、痴。】",
