        "passageTitle": "改寫自李渝〈賈政不做夢〉",
        "passage": "賈政這面鏡子,映照的性質和賈政正相反。寶玉有來自上天的靈竅稟賦,賈政的鏡性卻來自人間現實環境。眾人都在做夢時,只有賈政是醒著的。小說家給予賈政重任,讓他興建家園、重整家園,在各種緊要關頭,起動警惕、總結、前瞻等作用。\n賈政恨寶玉不務正,專在「濃詞豔賦上作工夫」。賈政打寶玉,是邊怒打邊流淚。賈政一路提醒寶玉什麼是現實生活,隨時鞭策寶玉,催促寶玉醒來,必須接受歷練而成長成熟,否則不能做好自己繼賈府的準備。賈政是成人的標徵。作者肯定賈政,善待成年,成年在小說中不是罪過,反被認知成生命的必要階段。賈政其實是瞭解寶玉的,寶玉的詩才之情,大多要憑和賈政對話的場合才更顯精神。在痛恨兒子是無用之人的同時,作父親的卻也一眼看得見他的奇異天生。\n我們終於明白了批評家脂硯齋所言——賈政之為人物,「有深意存焉」。是賈政,扶養寶釵母子;是賈政,攜賈母和黛玉等靈柩葬南鄉;是他,送別寶玉。只有賈政可以撫慰生者,安息逝者,讓離者心安地去了。如果寶玉是承盡了愛和哀,賈政則是擔盡了了事和責。\n即使是生命中不可能達致的,賈政依舊呵護成長尚未到來的浪漫存在,嘗試建立人間樂園烏托邦。寶玉是補天之石,支撐著現實人間的則是賈政。(改寫自李渝〈賈政不做夢〉)",
        "question": "依據上文,關於賈政與賈寶玉的父子關係,敘述最適當的是:",
