        "question": "依據上文,下列文句畫線處所暗示的情緒訊號,解讀最適當的是:\n(A)其(嫦娥)聲清越,烈如簫管。歌畢,盤旋而起,躍登几上,驚顧之間,已復為嫱——眾人臉上露出驚訝的表情而把目光集中在嫦娥身上\n(B)客喜而笑,洗盞更酌。肴核既盡,杯盤狼藉。相與枕藉乎舟中,不知東方之既白——蘇軾與客藉著疏狂的身體姿態表達對人生苦短的感傷\n(C)言訖,乘驢而去,其行若飛,回顧已失。靖與張氏且驚且喜,久之,曰:「烈士不欺人,固無畏!」促鞭而行——李靖夫婦快馬加鞭的身體動作,表現二人驚懼之下急於離開\n(D)親賢臣,遠小人,此先漢所以興隆也;親小人,遠賢臣,此後漢所以傾頹也。先帝在時,每與臣論此事,未嘗不嘆息痛恨於桓、靈也——劉備低聲嘆息,凸顯其極力壓抑面部表情與聲音",
