        "passage": "父子,人倫之大。父老而子不能事,則其罪在子;子幼而父不能養,則其責在父。\n劉珵為衡州知郡孫,有男元老,幼不撫養,而貴與鄉民鄭七。棄衣冠而服田畝,情亦可憐,此猶可諒也,曰劉珵一時為貧之故。已而,元老不安於鄭七家,逃拆本父,到劉珵固宜復回天理,自子其子矣,乃復以元老賣與程十乙,則其意在安在?可謂敗人倫、滅天理之已甚者!今鄭七入詞,欲取回元老於已去三年後,此決無復合之理。……劉珵兩將元老賣弄,為父不父,本合勘杖,且從寬減,決小杖二十。元老誅押往族長萬二宣宅,聽從收養。觀此子情貌好乖,兼所習已乖,為衣冠之玷,亦一美事。(《名公書判清明集》)\n【入詞:具狀陳述。宣教:宣教郎,官名。】",
