        "passageTitle": "改寫自蘇珉玟《唐代科舉與文學》",
        "passage": "唐代稱主掌考試為知貢舉。因知貢舉者有取捨大權,舉子便在考試前向其投獻詩文,以博得青睞,一旦登第,感恩終生,於是產生特有的「座主」與「門生」關係。柳宗元〈與顧十郎書〉中說:「凡號門生而不知恩之所自出者,非人也。」崔群的例子也反映了當時這種社會意識。崔群在中唐時被舉為賢士,韓愈盛讚他「考之言行而無瑕尤」,但他對座主與門生關係,卻表露出相當世俗的看法。《獨異志》云:\n崔群為相,清名甚重。元和中,自中書舍人,既罷,夫人李氏嘗勸其樹莊田以為子孫之計。笑曰:「余有三十所美莊良田遍天下,夫人復何憂?」夫人曰:「不聞君有此業。」群曰:「吾前歲放春榜三十人,豈非美良田?」夫人曰:「若然者,君非陸相門生?然往年君掌文柄,使人約其子(簡禮),不令就春之試。如君以為良田,則陸氏一莊荒矣。」群漸而退,累日不食。\n以莊園比喻門生,極易為唐代人所接受。及第的舉子若違世俗,就是柳宗元指斥的「非人也」。(改寫自蘇珉玟《唐代科舉與文學》)\n【陸相:陸贄。】",
        "question": "下列敘述,可藉由上文判斷確知的是:",
