        "passageTitle": "改寫自戴寶村《臺灣的海洋史文化》",
        "passage": "臺灣位處廣闊海洋中,島上不同族群,都有海洋活動的歷史經驗。部分史前族群和平埔族人駕駛側翼板的船隻配合洋流、季風遠航,阜南族有祭海祭典,達悟人更是典型的海洋民族。清帝國治臺期間,福建、廣東人民冒險渡過黑水溝來臺灣,其冒險打拚、追求「出頭天」的精神,成為臺灣強韌生命力的根源。1949年,大量移入的新住民,增加了臺灣社群構成的多樣性。而兩波移民雖原籍地與背景不同,「過鹹水」則是共同的歷史記憶。\n明、清時期的閩南移民,帶來冒險謀利的商業性格。臺灣從南到北港口林立,顯示蓬勃發展的生命力。大航海時代,東亞海域在國際貿易上的地位日漸重要,而臺灣因地處此一海域的交通要衝,遂成為各國進行商業交易的集散地。西班牙、荷蘭先後占領臺灣,將臺灣推向西方近代化的進程,也帶來商業文明的思維。回望歷史,中國、日本、南亞與西方國家的文化在此地交流,並融合原民的南島文化,形成特殊的臺灣文化。(改寫自戴寶村《臺灣的海洋史文化》)",
