        "passageTitle": "硃砂資料(行政院衛生署公告、中醫師說明)",
        "passage": "關於硃砂(主成分為硫化汞),符合下列資料所述的是:\n【行政院衛生署公告(署授藥字第0940002424號)】主旨:自94年5月1日起,禁止中藥用硃砂製造、調劑、輸入、輸出、販賣或陳列。\n【中醫師】我家因硃砂礦業而致富。硃砂應視原料品質與加工目的,而有不同的處理方式。炮製藥用硃砂,須重複水飛法多次方可,耗時費力。若不肖者私下以機器研磨,會因機轉的高溫,使硃砂產生劇毒,一旦入藥,極其危險。\n【水飛】惟取好砂,軋碎如微塵,入紅注清水澄浸三日夜,其上浮者不堪入藥,傾入別紅。其下沉結者,曬乾即頭朱也。\n【升煉】次砂不入藥,作爐置砂於中,下承以水,上覆以盆,器外加火,則煙飛于上,水銀溜于下。丹砂性寒而無毒,入火則熱而有毒,能殺人。水銀乃至陰毒物,因火煅丹砂而出,或加鹽、礬煉而為輕粉,或加硫黃升而為銀朱。\n【古文敘述參考《天工開物》、《本草綱目》。】",
