        "question": "關於丙、丁二詞中的夢與現實,解讀最適當的是:(占2分,單選題)\n(A)夢中皆突破局限,穿梭過去、現在與未來,虛實相生\n(B)皆自歡快的夢境中醒來,從生發想望落空的幻滅感\n(C)李煜夢醒覺知「身是客」,辛棄疾夢中自憐「白髮生」\n(D)夢醒後,對照夢境與當前的境遇,皆萌生壯志未酬之嘆",
