        "question": "若參照甲文理解丙、丁二詞,請回答下列問題:\n(1)丙詞以「天上人間」的對比表達感受,亦暗示作者意識到怎樣的「自我」變化?(占2分,作答字數:20字以內。)\n(2)夢是文學家表述記憶的一種手法。假設丁詞「夢回」後所寫的夢境,屬於「不由自主的回憶」,詞中何者是「提醒物」?它與作者回憶起的往事有何關聯?(占4分,作答字數:30字以內。)",
        "explanation": "【滿分參考答案】\n(1)由帝王淪為囚徒\n或:由生命的主人變成受人宰制的人\n(2)劍;劍是他征戰沙場的工具\n或:劍;讓他想起曾馳騁於戰場\n\n【評分原則】\n第36題(1):能正確寫出參考答案之文句 2分;未作答或答案完全錯誤 0分。\n第36題(2):能寫出參考答案大意,且敘述完整 4分;答案敘述部分錯誤或不完整 2分;未作答或答案完全錯誤 0分。\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
