        "sourceYear": 114,
        "question": "丘成桐是知名數學家,下文將數學與文學並談,主要用意是強調:\n《詩經》的「北風其涼」,假風以刺威虐;「雨雪霏霏」,因雪以悲征役——皆興發於此而義歸於彼。有深度的文學作品必須有「義」、有「比興」,數學亦如是。我們在尋求真知時,往往只能依循研究的大方向,憑著對大自然的感覺邁進,這種感覺因個人的修養而定。文學家為了描述最佳意境,不見得忠實描寫現實界。如賈島追究「僧推月下門」與「僧敲月下門」的區別,並不在乎所說的是不同的事實。數學家創造美好的理論,也不必依隨大自然的規律,只要邏輯推導沒有問題,就可以盡情發揮想像力。(改寫自丘成桐〈數學和中國文學的比較〉)",
