        "passageTitle": "改寫自林文月〈山笑〉",
        "passage": "深夜,斜臥床榻,隨手抽取一本几上疊放的書漫讀助眠,已是長年習慣。書宜輕巧易掌握,內容切勿過於深奧嚴肅,否則刺激興奮,反失效果。那夜,從書堆抽出體積特小的日本岩波書店口袋型書,曾閱讀過部分而未竟,書頁間夾著一張書籤,姑且從有書籤的那頁讀起來。翻閱兩三頁後,忽有一張小小的短箋滑下,上面印著淺淺好看藍紫色的鉛印字:\n【山笑——根據《廣辭苑》\n俳句的季節語。謂萌樹一齊吐芽的春季華麗景致。相對的,「山眠」指枯槁失卻精采的山,「山粧」則是被紅葉裝扮的山,各為冬、秋季節語。見於北宋畫家、兼山水畫理論家郭熙的「四時山」。\n《廣辭苑》雖未採入,但青青的夏季的山是「山滴」。】\n這幾行文字與我手中捧讀的書全不相關。把紙片反過來看,正中央印著岩波書店新印製的辭典《廣辭苑》書影樣本,原來正面文字是為第五版《廣辭苑》做的廣告。\n廣告何以題為「山笑」,又引用郭熙「四時山」的字句呢?根據《廣辭苑》,「山笑」一詞,是俳句(日本古典短詩)的季節語,典出於北宋郭熙的《山水訓》。按捺不住好奇,索性走到書房去查究。《山水訓》的原文是這樣的:「真山水之煙嵐,四時不同。春山淡冶而如笑,夏山蒼翠而如滴,秋山明淨而如粧,冬山慘淡而如睡。」雖然日文廣告詞引述的文字,把原文的「如笑」、「如滴」、「如粧」、「如睡」改為「山笑」、「山滴」、「山粧」、「山眠」,以適合其語言習慣,且文章次序也略有變動,但郭熙的絕妙比喻,卻被生動地化為一則含帶商業性質的文字裡,不得不令人佩服!至於在四季不同山色中擇取「山笑」為題,從我正在閱讀的書印刷發行時間推斷,應是配合此書是春季版的效果,也是神來之筆。\n日本的文士不僅寫作漢詩文,即使和歌、俳句也深受中國文化影響,這段廣告詞可以為證。查這些來龍去脈,我心中釋然,雖則睡意全消,卻經驗了一次愉悅的失眠。(改寫自林文月〈山笑〉)",
        "question": "有關書中紙片訊息的解讀,敘述最適當的是:",
