        "passageTitle": "改寫自李漁〈閒情偶寄‧廳壁〉",
        "passage": "廳壁不宜太素,亦忌太華。名人尺幅,自不可少,但須濃淡得宜,錯綜有致。予謂裱軸不如實貼;軸慮風起搖蕩,損傷名跡,實貼則無是患,且覺大小咸宜也。實貼又不如實畫,「何年顧虎頭,滿壁畫滄洲」自是高人韻事。予嘗頭偶仿此制,而又變幻其形,良至止焉,無不耳目一新,低回留之不能去者。\n因予性嗜禽鳥,而又最惡樊籠,二事難全,終年搜索枯腸,一悟遂成良法。乃於廳旁四壁,倩四名手,盡寫著色花樹,而繞以雲煙,即以所愛禽鳥,蓄於蚪枝幹之上。畫止空跡,鳥有實形,如何可蓄?曰:不難,蓄之須自鸚鵡始。從來蓄鸚鵡者必用銅架,即以銅架去其三面,止存立腳之一條,並飲水啄粟之二管。先於所畫松枝之上,穴一小小壁孔,後以架鸚鵡者插入其中,務使堅固,庶往來跳躍,不致動搖。松與著色之松,鳥亦有色之鳥,互相映發,有如一筆寫成。\n良朋至止,仰觀壁畫,忽見枝頭鳥動,葉底翎張,無不色變神飛,詫為仙筆;乃驚疑未定,又復戴飛戴鳴,似欲翱翔而下矣。諦觀熟視,方知個裡情形,有不抵掌叫絕,而稱巧奪天工者乎?(節錄自李漁《閒情偶寄‧廳壁》)\n【顧虎頭:東晉畫家顧愷之。滄洲:古稱隱士居住的地方。】",
        "question": "根據上文朋友抵掌稱「巧奪天工」的原因,最可能的是:",
