        "question": "下列文句,意在表達「有其他概念框架可以選擇」的是:(占2分,單選題)\n(A)河內凶,則移其民於河東,移其粟於河內。河東凶,亦然\n(B)竊慕管夫人之墨竹,紙上生風;敢藉陶彭澤之黃花,圖中寫影\n(C)彼節者有間,而刀刃者無厚,以無厚入有間,恢恢乎其於遊刃必有餘地矣\n(D)若亡鄭而有益於君,敢以煩執事。越國以鄙遠,君知其難也,焉用亡鄭以陪鄰",
