        "question": "上文中,虯髯客、孫悟空的某些行為,曾讓虯髯客、唐僧動怒,請回答下列問題:\n(1)李靖基於什麼身分框架,對虯髯客「取枕敧臥,看張氏梳頭」動怒?虯髯客這項舉動為何讓李靖如此介意?(占4分,作答字數:30字以內。)\n(2)唐僧對孫悟空打死強盜如此介意,是因為此舉損害了他所認定的什麼身分框架與特質?(占2分,作答字數:15字以內。)",
        "explanation": "【滿分參考答案】\n(1)他是紅拂的伴侶,不容許虯髯客有非分之想。\n(2)出家人的框架,慈悲為懷。\n\n【評分原則】\n第34題(1):能寫出參考答案大意,且敘述完整 4分;答案敘述部分錯誤或不完整 2分;未作答或答案完全錯誤 0分。\n第34題(2):能正確寫出參考答案之文句 2分;未作答或答案完全錯誤 0分。\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
