        "question": "上文中,虯髯客一度看不起李靖,後來才改變看法,請回答下列問題:\n(1)虯髯客問李靖「何以致斯異人」,透露了他推測李靖也許不是等閒之輩,他如此推測的前提是什麼?(占2分,作答字數:15字以內。)\n(2)虯髯客進一步觀察李靖的「儀形器宇」,認為他的哪些表現符合「真丈夫」框架?請舉出一項,參考下表中示例,填寫①、②。(占4分,作答字數:①10字以內;②20字以內。)\n| 李靖的表現 | 這項表現,符合「真丈夫」的什麼特質 |\n| 示例:自言貧而有心 | 示例:雖然尚未顯達,卻胸懷大志。 |\n| 作答:①____ | 作答:②____ |",
        "explanation": "【滿分參考答案】\n(1)紅拂聰慧,故李靖應非等閒之輩。\n(2)①避地太原;②能投明主\n或:①吃負心人的心肝;②有膽識\n\n【評分原則】\n第36題(1):能正確寫出參考答案之文句 2分;未作答或答案完全錯誤 0分。\n第36題(2):能寫出參考答案大意,且敘述完整 4分;答案敘述部分錯誤或不完整 2分;未作答或答案完全錯誤 0分。\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
