        "passageTitle": "鄭用錫、林占梅相關詩文資料(甲/乙)",
        "passage": "甲、鄭用錫、林占梅為清代新竹文學名家,鄭用錫次子鄭如梁娶林占梅之妹為妻。林占梅年幼喪父,由友父林祥雲撫養成人。\n乙、鄭用錫曾寫給林占梅一首祝賀詩:「四方男子志,今更挂桑弧。天上誕麟種,人間浴鳳雛。共詩田冒玉,早叶夢投珠。清福知誰享,孤山一幅圖。」",
        "question": "依據資料甲、乙,下列敘述最適當的是:",
