        "passage": "【有這些情況,國家可能走向敗亡啊!\n①大臣甚貴,偏黨眾強。\n②聽以爵,不以參驗。\n③無禮於大鄰,貪愎而拙交。\n④境內之傑不事,而求封外之士。\n⑤財物寡,無守戰之備而輕攻伐。\n⑥大臣隆盛,外藉敵國,內困百姓,以攻怨讎。\n——韓非】",
