        "origNo": 5,
        "sourceYear": 115,
        "question": "下列是一段古文,依據文意,甲、乙、丙、丁、戊排列順序最適當的是:\n夫三代之君,惟不忍鄙其民而欺之,\n甲、及其不可聽也\n乙、以觀其意之所憚\n丙、而服其不然之心\n丁、故天下有故,而其議及於百姓\n戊、則又反覆而諭之,以窮極其說\n是以其民親而愛之。(蘇軾〈書論〉)",
