        "passageTitle": "改寫自馬丁‧費德著,柯清心譯《柯南‧道爾所不知道的福爾摩斯》",
        "passage": "《福爾摩斯新探案》是柯南‧道爾的福爾摩斯系列最後一本短篇小說集。其中,〈王冠寶石案〉使用第三人稱的敘述方式,這種寫法,少了華生作為敘述者特有的平靜和虔敬,在先前的小說集裡僅見於〈最後致意〉。\n【華生:福爾摩斯的助手。】\n〈王冠寶石案〉不但老套地「把福爾摩斯蠟像擺在窗口」,部分細節也出現疑點。一般讀者難不必像福爾摩斯那樣,知道在1903年之前,歌劇《霍夫曼的故事》裡的〈威尼斯船歌〉從未出版過任何小提琴獨奏的唱片,但多少知道那個年代的唱片或圓筒錄音,不可能持續播五分鐘,掩護福爾摩斯偷聽其他人的對話。\n小說集裡另有兩篇故事由主人翁福爾摩斯自述,這全新的寫法替兩篇小說增色。〈皮膚變白的軍人〉有人在麻風病患的床上睡過一夜,竟染上一種不是麻風病卻狀似麻風病的病症,這種巧合實在牽強。又先前的故事說華生太太死於1893年,這故事卻說發生在1903年華生結婚期間,福爾摩斯迷於是懷疑喬長女的華生結過不只一次婚。\n至於〈獅鬃毛〉,先別管故事裡的水母,若真有那麼危險,問題是,福爾摩斯說他原先未發現參菲遊死於海王物專,是因為他看到死者的毛巾是乾的,以致誤判死者沒下過水。如此說來,參菲遊與殺人水母纏鬥時,半根頭髮都沒溼嗪……疾!\n身為醫生的柯南‧道爾,曾在1891年公開指出科赫宣稱「結核菌素治療結核病」絕不可信。由於當時不少人接受沃羅諾夫醫生說明的回春手術,將動物腺體移植到人類身上,他寫下小說集裡的〈飛行人〉,描寫一名著名生理學教授注射了一種據稱能返老還童的藥後,出現嚴重的畸變,他再以此批判現實世界的偽科學。(改寫自馬丁‧費德著,柯清心譯《柯南‧道爾所不知道的福爾摩斯》)",
        "question": "上文第三段末尾的「唉」,感嘆的原因最可能是:",
