        "passageTitle": "改寫自余英時〈俠與中國文化〉",
        "passage": "從十一世紀末到十世紀初,西方史家大致都承認這期間是騎士的鼎盛時代,由騎士構成西方武力的主體。從國家的觀點來看,騎士與文吏平行,構成王國的左右手,前者代表武力,後者代表法律。與此相對,中國的「俠」即使在力極盛的西漢,也沒有成為國家武力的一部分。相反地,「俠」的武力在朝廷眼中是敵對性的,必須加以消滅。\n自漢代以來,中國社會一天天走上文吏的道路,「俠」作為武力集團終於解體,後來甚至也不必然和「武」連在一起。自東漢起,「俠」突破了「武」的領域,成為一種超越精神,並進入儒生文士的道德意識中。故論及「俠」對中國文化的影響,不能不特別注重「俠」與「士」的關係。\n和西方騎士相似,中國古代的「士」一方面承擔著建立和維持政治、文化秩序的任務,另一方面又發展出不肯屈服於權威、持「道」以議政的批判傳統。我們通常認定這一傳統的來源在儒家,這個判斷大體上是有根據的。然而從東漢名士的集體反抗行動來看,「俠」見義勇為的作風有極其重要的影響。當時的黨錮之士在道理上固然以儒家為依歸,激昂慷慨的俠節卻提供了他們情感上的動力,後世富於批判精神的儒者也往往帶有「俠氣」。這一發展其實也是很自然的,因為儒家傳統中本有一股「狂」的精神,能與「俠風」一拍即合。(改寫自余英時〈俠與中國文化〉)",
        "question": "依據上文,關於中國古代的「俠」,敘述最適當的是:",
