        "passageTitle": "懷素〈自敘帖〉相關",
        "passage": "西元八世紀左右的盛唐,出現一種新型態的草書,後人以「狂草」稱呼。唐代狂草真跡存世者寥寥無幾,草書名品多以摹本、臨本、仿本或刻本的形式廣為流傳。今傳世名聲最大、影響最廣的狂草作品,堪稱唐代僧人懷素的〈自敘帖〉長卷。\n〈自敘帖〉本幅部分書有126行,702字,是懷素自述出身、經歷與交遊的重要文獻。懷素二十餘歲即以草書聞名,並以驚人的即席表演結交當代名公。〈自敘帖〉中將近一半篇幅節錄眾人觀其作書有感而所撰之詩作,描述他在眾人圍觀下的激昂揮毫的景況,例如:「奔蛇走虺勢入座,驟雨旋風聲滿堂」、「筆下唯看激電流,字成只見盤龍走」、「醉來信手兩三行,醒後卻書書不得」、「心手相師勢轉奇,詭怪狀翻合宜」、「忽然絕叫三五聲,滿壁縱橫千萬字」、「遠鶴無前侶,孤雲寄太虛。狂來輕世界,醉裡得真如」等,為八世紀的書法表演現場留下難得的紀錄。懷素的書法表演頗富神異色彩,筆下充滿驚奇的物象變化,詩作中還有人強調連懷素自己也不知如何寫成的。在觀賞者眼中,懷素能在草書中興風作浪、幻化出種種物象的能力,恐怕是當時人的普遍認知與期待,是唐代佛道盛行、社會瀰漫濃厚宗教氛圍下的產物。\n〈自敘帖〉書法用筆迅速,筆勢連綿,然字形結構謹守草法,線條穩定圓轉。全卷可見節奏緩起漸快,卷中段以後筆意豪放,但絕非倚靠靈感驅使的即興之作。國立故宮博物院藏本〈自敘帖〉,每行第一字墨色飽滿,漸寫漸乾,直到寫完行末最後一字。所謂「法度」看似不存在,卻其實無所不在,是興風作浪的浪漫藉以依存的基礎。\n(改寫自盧慧紋〈興風作浪的浪漫〉)",
        "question": "依據上文,關於〈自敘帖〉中詩作對懷素其人其書的描述,說明最適當的是:",
