        "passageId": "chinese-real-115-p29",
        "passageTitle": "孔子論樂敘事二則(甲/乙,《韓詩外傳》)",
        "passage": "【甲】孔子學鼓琴於師襄子而不進。師襄子曰:「夫子可以進矣!」孔子曰:「丘已得其曲矣,未得其數也。」有間,曰:「夫子可以進矣!」曰:「丘已得其數矣,未得其意也。」有間,復曰:「夫子可以進矣!」曰:「丘已得其人矣,未得其類也。」有間,曰:「……必作此樂也,黯然而思,戚然而悲,以王天下,其惟文王乎?」師襄子避席再拜曰:「善!師以為文王之操也。」(《韓詩外傳》)\n【乙】孔子鼓瑟,曾子、子貢側門而聽。曲終,曾子曰:「嗟乎!夫子瑟聲始有貪狼之志,邪僻之行,何其不仁,趙利之甚?」子貢以為然,……以曾子之言告。子曰:「……丘鼓瑟,有鼠出游,狸見於屋,循梁微行,造焉而避,厭目曲脊,求而不得,丘以瑟淫其甚,不亦宜乎!」(《韓詩外傳》)",
