        "passageTitle": "出師表相關評述(甲/乙/丙)",
        "passage": "【甲】〈出師表〉違異了「表」的典型特質。全篇始於「臣亮言」,但這位說話的「臣」受到備遺命:「若嗣子可輔,輔之,如其不才,君可自取」,其實具有廢立的權柄。文中十三次提及「先帝」,使「陛下」成了虛位,故「討賊興復之效」乃因下「託」臣而非「命」臣。又此表也不以「誠惶誠恐,稽首頓首」結束,而是頗具生離死別意味的真情流露:「今當遠離,臨表涕泣,不知所云」,是以格外感人。(改寫自柯慶明〈「表」、「奏」作為文學類型之美感特質的研究〉)\n【乙】今南方已定,兵甲已足,當獎率三軍,北定中原。庶竭駑鈍,攘除姦凶,興復漢室,還於舊都,此臣所以報先帝而忠陛下之職分也。至於斟酌損益,進盡忠言,則攸之、禕、允之任也。願陛下託臣以討賊興復之效,不效,則治臣之罪,以告先帝之靈。若無興德之言,則責攸之、禕、允等之慢,以彰其咎。陛下亦宜自課,以諮諏善道,察納雅言,深追先帝遺詔,臣不勝受恩感激。今當遠離,臨表涕泣,不知所云。(諸葛亮〈出師表〉)\n【丙】陛下即祚,復蒙試用,遂受上將之任,統領二州,內參機事,實所不堪。……臣以區區之質,而當鐘鼎之任;以闇鈍之才,而奉明時之政。顧恩念責,亦竭節授命之秋也。謹條遵奉舊訓權時之宜十四事,奏以上,庶以蒸螢增明太陽,言不足採。(曹操〈陳損益表〉)\n【東漢建安元年,曹操迎漢獻帝至許都,受封司空,進呈此表。】",
        "question": "甲文運用文體知識,深入解讀乙文表層文字下的聲音,若循此方式觀察丙文,關於乙、丙文違異「表」的典型特質,敘述適當的是:",
