        "question": "乙文的「我」、丙文的「六女兒」皆因自我的覺醒,而以具體行動勇敢挑戰傳統觀念。請回答下列問題:\n(1)乙文的「我」,基於何種考量,因此而採取了什麼行動?(占4分,作答字數:合計40字以內。)\n(2)丙文的「六女兒」,基於何種認知,因此而採取了什麼行動?(占4分,作答字數:合計30字以內。)",
        "explanation": "【滿分參考答案】\n(1)基於讓孩子學習認識自己的負面情緒,耐心陪伴孩子。\n或:基於讓小孩有表達情緒的自由,承受譴責,對抗長輩高壓控制的教養方式。\n(2)基於婚姻要有感情基礎,不接受「作新娘」的安排。\n或:基於與養兄沒有感情,拒絕與養兄結婚。\n\n【評分原則】\n第34題(1):能寫出參考答案大意,且敘述完整 4分;答案敘述部分錯誤或不完整 2分;未作答或答案完全錯誤 0分。\n第34題(2):能寫出參考答案大意,且敘述完整 4分;答案敘述部分錯誤或不完整 2分;未作答或答案完全錯誤 0分。\n\n(此為非選擇題,系統不自動判分,請對照以上官方滿分參考答案與評分原則自行評估作答情形。)"
