        "question": "關於甲、乙、丙文所呈現的「她的聲音」,敘述最適當的是:(占2分,單選題)\n(A)甲文中敘寫三位女性親屬的聲音各有用意,如「持笏」即暗喻大母為家中掌權者\n(B)乙文是女性主動發聲,「黑色河流」、「黑森林」的比喻委婉傳達反抗傳統的不安\n(C)丙文記錄受訪者及其記憶中他人的聲音,敘事的時間跨度大,事件場景未必其親歷\n(D)三文皆呈現不同世代女性的聲音,代間隔閡雖不免形成對立,最終仍能找到平衡點",
