        "passage": "在文學與歷史的敘事中,女性的聲音長期被忽略、壓抑或誤讀……「聽見她的聲音」,不僅是在文本中發掘女性話語的紀錄,更在於理解女性能否主動發聲,或如何被表達、被建構。\n我認為:三代王教修明,內外順治,「閨門之事皆可歌詠而傳道之」。所述雖「婦人女子之常」,而事之至微者,但「幽閑貞靜之德,隱然寓於其間」,而足以章明王者之化。可惜的是,此後女子在史傳作者眼中,必有「非平常之行」,乃能「著美名」於後世,導致女性「罕可紀述」,幾近銷聲匿跡。\n【甲】下列三段節錄文字,都出自歸有光的作品:\n〈項脊軒志〉:一日,大母過余曰:「吾兒,久不見若影,何竟日默默在此,大類女郎也?」比去,以手闔門,自語曰:「吾家讀書久不效,兒之成,則可待乎?」頃之,持一象笏至,曰:「此吾祖太常公宣德間執此以朝,他日汝當用之。」\n〈先妣事略〉:有光七歲,與從兄有嘉入學。每陰風細雨,從兄輒留,有光意戀戀,不得留也。孺人中夜覺寢,有光暗誦《孝經》,即熟讀,無一字齟齬,乃喜。\n〈祭外姑文〉:昔吾亡妻,能孝於吾父母,友於吾兄弟,知夫人(按:即外姑,指妻子的母親)之能教也;粗食之養,未嘗不甘,知夫人之儉也。\n\n【乙】作為一位母親,如果不選擇「你無理取鬧,我不睬你」,也不以打罵碎唸管束,那麼她所碰上的難題不但超乎想像,要處理的委屈恐怕也成倍增長。如果長輩在旁,複雜度往往更高。想耐心等待哭泣的雲朵飄去,接納他表達情緒的自由時,就會被貼上「怎麼都不教小孩?」「不教以後他長大很難控制」的標籤。我練習克制脾氣,盡可能耐心走過他們哭泣、踢東西等情緒。有時得忍耐讀責,背對著理所當然的教養方式,爭取時間讓孩子認識自己的負面情緒。看看內心湧動出多少黑色河流,在高大濃密的黑森林裡,試著踏出一條日光照得到的路徑。(改寫自李欣倫〈水面下〉)\n\n【丙】以前生活比較艱苦,小孩又多,養不活,很多人只好把女兒送給人家做媳婦仔。我們也不例外,七個女兒中除了最大的和最小的,其餘那五個都曾經送給別人養。第六個女兒養到四、五歲時,庄嬸婆又來強要我們把女兒送給她親戚,一直說:「她會疼她啦!她只有兩個兒子而已!」我先生只好又把女兒抱給他們。那麼多個女兒都是他抱給人家送走的,我都不忍心,把頭轉走,不敢看。這個女兒真的是「媳婦仔王」,因為他們沒有生女兒,所以很疼愛她。但後來要她「作新娘」,沒想到她還是不肯,實在對不住。因為她和養兄沒有感情,不願意和他結婚。她養母很生氣,但養父親自來家裡跟我們說:「她已經和一個男的在交往,人家也打算來訂親了。」那個男的我去探聽過,聽說很乖啦!既然不能在一起,就不要勉強。不然,像我這樣,就一輩子不幸福了。」她養母也是小時候養大的,「作新娘」後,兩個感情還是不好。(改寫自曾秋美訪問整理《消失中的臺灣阿嬤‧將女兒送養的阿母——曾林阿珠》)",
        "question": "依據本題組所有資料,下列關於「她的聲音」被「聽見」的推論是否正確,最適當的研判是:(占2分,單選題)\n①舊時代的女性常因社會限制而受到忽略,人們甚至視靜默不出聲為女性的特質。\n②教育普及促使當代關注女性的聲音,女性的自我敘說往往比受訪紀錄更直擊人心。\n③看重非平常之行的史傳使女性聲音難以真實呈現,當代口述歷史則呈現多元的聲音。\n(A)①、③皆正確,②無法判斷 (B)①、②皆無法判斷,③正確\n(C)①錯誤,②無法判斷,③正確 (D)①正確,②錯誤,③無法判斷",
        "options": [
          "①、③皆正確,②無法判斷",
          "①、②皆無法判斷,③正確",
          "①錯誤,②無法判斷,③正確",
          "①正確,②錯誤,③無法判斷"
        ],
        "answer": 0,
